 void interruptedRecovery(){
  QString project=QFileInfo(QString::fromUtf8(__FILE__)).dir().absoluteFilePath("..");QDir().mkpath(project+"/data/tests");QTemporaryDir temp(project+"/data/tests/recovery-XXXXXX");QString root=temp.path();{Library lib(root,project+"/helpers","");}
  sqlite3* db=nullptr;QByteArray p=(root+"/library.sqlite3").toUtf8();QCOMPARE(sqlite3_open(p.constData(),&db),SQLITE_OK);QCOMPARE(sqlite3_exec(db,"INSERT INTO jobs(id,kind,args,state,created,updated) VALUES('interrupted','issue.scan','{}','running','0','0')",nullptr,nullptr,nullptr),SQLITE_OK);sqlite3_close(db);
  Library reopened(root,project+"/helpers","");QCOMPARE(result(reopened,"job.get",{{"job_id","interrupted"}})["state"].toString(),"interrupted");auto retry=result(reopened,"job.retry",{{"job_id","interrupted"}});QVERIFY(retry["id"].toString()!="interrupted");QCOMPARE(wait(reopened,retry["id"].toString())["state"].toString(),"completed");
 }
 void failuresAndConcurrency(){
  QString project=QFileInfo(QString::fromUtf8(__FILE__)).dir().absoluteFilePath("..");QDir().mkpath(project+"/data/tests");QTemporaryDir temp(project+"/data/tests/failures-XXXXXX");QString root=temp.path();QString source=root+"/原件.png";QImage pixel(16,16,QImage::Format_RGBA8888);pixel.fill(Qt::green);QVERIFY(pixel.save(source));Library lib(root+"/库",project+"/helpers",project+"/.tools/adapters-env/Scripts/python.exe");auto import=run(lib,"asset.import",{{"paths",QJsonArray{source}},{"backup",true}});QCOMPARE(import["state"].toString(),"completed");QString aid=import["result"].toObject()["asset_ids"].toArray()[0].toString();auto original=result(lib,"asset.get",{{"asset_id",aid}});
  auto params=QJsonObject{{"asset_id",aid},{"revision",original["revision"]},{"values",QJsonObject{{"favorite",true}}}};
  auto first=QtConcurrent::run([&]{return call(lib,"asset.update",params);});auto second=QtConcurrent::run([&]{return call(lib,"asset.update",params);});first.waitForFinished();second.waitForFinished();QCOMPARE(int(first.result().contains("result"))+int(second.result().contains("result")),1);QCOMPARE((first.result().contains("error")?first.result():second.result())["error"].toObject()["code"].toString(),"revision_conflict");
  QString invalidDestination=root+"/not-a-directory";write(invalidDestination,"occupied");auto exportFailure=run(lib,"export.assets",{{"asset_ids",QJsonArray{aid}},{"destination",invalidDestination}});QCOMPARE(exportFailure["state"].toString(),"failed");QVERIFY(QFileInfo(source).isFile());
  auto dependency=original["dependencies"].toArray()[0].toObject();QString objectPath=root+"/库/objects/"+dependency["hash"].toString()+".zst";write(objectPath,"corrupt zstd test object");QVERIFY(QFile::remove(source));auto resolve=result(lib,"asset.resolve",{{"asset_id",aid}});QCOMPARE(wait(lib,resolve["job_id"].toString())["state"].toString(),"failed");QCOMPARE(run(lib,"issue.scan",{})["state"].toString(),"completed");bool corrupt=false,missing=false;for(auto value:result(lib,"issue.list")["items"].toArray()){auto issue=value.toObject();corrupt|=issue["kind"]=="backup_corrupt";missing|=issue["kind"]=="source_missing";}QVERIFY(corrupt&&missing);
  QString longDirectory=root;for(int i=0;i<14;++i)longDirectory+="/中文长路径_"+QString::number(i)+"_abcdefghijkl";QVERIFY(QDir().mkpath(longDirectory));QString longSource=longDirectory+"/图片.png";QVERIFY(pixel.save(longSource));QVERIFY(longSource.size()>260);QCOMPARE(run(lib,"asset.import",{{"paths",QJsonArray{longSource}}})["state"].toString(),"completed");
  QString many=root+"/批量取消";QVERIFY(QDir().mkpath(many));for(int i=0;i<300;++i)QVERIFY(pixel.save(many+QString("/%1.png").arg(i)));QString importId=result(lib,"asset.import",{{"paths",QJsonArray{many}}})["job_id"].toString();result(lib,"job.cancel",{{"job_id",importId}});QCOMPARE(wait(lib,importId)["state"].toString(),"cancelled");auto retry=result(lib,"job.retry",{{"job_id",importId}});auto retried=wait(lib,retry["id"].toString());QCOMPARE(retried["state"].toString(),"completed");QCOMPARE(retried["result"].toObject()["imported"].toInt(),300);QCOMPARE(result(lib,"asset.list")["total"].toInt(),302);
 }
