 void concurrentExportPreservesEveryOutput(){
  QString project=QFileInfo(QString::fromUtf8(__FILE__)).dir().absoluteFilePath("..");QDir().mkpath(project+"/data/tests");QTemporaryDir temp(project+"/data/tests/export-XXXXXX");QString root=temp.path();Library lib(root+"/library",project+"/helpers","");result(lib,"library.settings",{{"values",QJsonObject{{"job_concurrency",8}}}});
  QByteArray first(1024*1024,'a'),second(1024*1024,'b');write(root+"/a.png",first);write(root+"/b.png",second);write(root+"/mesh.bin",QByteArray(1024*1024,'m'));write(root+"/model.gltf",R"({"asset":{"version":"2.0"},"buffers":[{"uri":"mesh.bin","byteLength":1048576}]})");
  auto imported=run(lib,"asset.import",{{"paths",QJsonArray{root+"/a.png",root+"/b.png",root+"/model.gltf"}},{"backup",true}});QCOMPARE(imported["state"].toString(),"completed");QJsonArray images;QString model;
  for(auto value:result(lib,"asset.list")["items"].toArray()){auto a=value.toObject();if(a["type"]=="model")model=a["id"].toString();else{images.append(a["id"]);result(lib,"asset.update",{{"asset_id",a["id"]},{"revision",a["revision"]},{"values",QJsonObject{{"name","same.png"}}}});}}
  QCOMPARE(images.size(),2);QVERIFY(!model.isEmpty());QString destination=root+"/outputs";write(destination+"/same.png","existing output");
  for(int fromBackup=0;fromBackup<2;++fromBackup){if(fromBackup){QVERIFY(QFile::remove(root+"/a.png"));QVERIFY(QFile::remove(root+"/b.png"));QVERIFY(QFile::remove(root+"/model.gltf"));QVERIFY(QFile::remove(root+"/mesh.bin"));}QStringList jobs;for(int i=0;i<16;++i)jobs<<result(lib,"export.assets",{{"asset_ids",QJsonArray{i<8?images[i%2]:QJsonValue(model)}},{"destination",destination}})["job_id"].toString();QSet<QString>published;
   for(int i=0;i<jobs.size();++i){auto completed=wait(lib,jobs[i]);QCOMPARE(completed["state"].toString(),"completed");auto paths=completed["result"].toObject()["paths"].toArray();QCOMPARE(paths.size(),1);QString path=paths[0].toString();QVERIFY(!published.contains(path));published.insert(path);QFile file(path);QVERIFY(file.open(QIODevice::ReadOnly));QByteArray data=file.readAll();if(i<8)QVERIFY(data==first||data==second);else{QVERIFY(data.startsWith("{\"asset\""));QFile bin(QFileInfo(path).absolutePath()+"/mesh.bin");QVERIFY(bin.open(QIODevice::ReadOnly));QCOMPARE(bin.readAll(),QByteArray(1024*1024,'m'));}}
   QFile existing(destination+"/same.png");QVERIFY(existing.open(QIODevice::ReadOnly));QCOMPARE(existing.readAll(),QByteArray("existing output"));QCOMPARE(QDir(destination).entryList({".imagidock-export-*"},QDir::Dirs|QDir::Hidden|QDir::NoDotAndDotDot).size(),0);
  }
  QCOMPARE(QDir(destination).entryList({"*.png"},QDir::Files).size(),17);QCOMPARE(QDir(destination).entryList({"model*"},QDir::Dirs|QDir::NoDotAndDotDot).size(),16);
 }
