  {QFile file(texture);QVERIFY(file.open(QIODevice::Append));QCOMPARE(file.write("updated texture",15),15);}QCOMPARE(QFileInfo(source).lastModified(),originalTime);QCOMPARE(result(lib,"asset.get",{{"asset_id",aid}})["backup_state"].toString(),"stale");QCOMPARE(run(lib,"issue.scan",{})["state"].toString(),"completed");bool stale=false;for(auto value:result(lib,"issue.list")["items"].toArray()){auto issue=value.toObject();if(issue["asset_id"]==aid&&issue["kind"]=="backup_stale"){stale=true;QCOMPARE(issue["path"].toString(),texture);}}QVERIFY(stale);QCOMPARE(result(lib,"asset.list",{{"status","stale"}})["total"].toInt(),1);
